import Foundation
import Testing
@testable import VazCore

/// Definitions generated by tools/gen_j5_definitions.py --all for every serial J5 build.
@Suite struct J5DefinitionsTests {
    static let images: [String] = (try? j5CatalogImages().map(\.path)) ?? []

    @Test(arguments: images)
    func everyImageGetsItsDefinition(path: String) throws {
        let fw = try load(path)
        let def = try #require(fw.definition, "\(path): нет описания")
        #expect(def.softwareIDs.contains(fw.softwareID ?? ""))
        #expect(def.matches(fw.data))
        #expect(def.tables.count > 200, "\(path): \(def.tables.count)")
    }

    /// Grids come from the code that reads them in each build; they must look like grids.
    @Test(arguments: images)
    func gridsAreSane(path: String) throws {
        let fw = try load(path)
        let def = try #require(fw.definition)
        let rpm = try #require(def.axes["rpm16"]?.values(in: fw.data), "\(path)")
        #expect(zip(rpm, rpm.dropFirst()).allSatisfy { $0 < $1 }, "\(path): \(rpm)")
        #expect((400...1000).contains(rpm[0]) && (5000...9000).contains(rpm[15]), "\(path): \(rpm)")
        let load = try #require(def.axes["load16"]?.values(in: fw.data), "\(path)")
        #expect(zip(load, load.dropFirst()).allSatisfy { $0 < $1 } && load[0] > 0, "\(path): \(load)")
        if let thr = def.axes["throttle16"]?.values(in: fw.data) {
            #expect(thr[0] == 0 && (80...100).contains(thr[15]), "\(path): \(thr)")
        }
    }

    @Test(arguments: images)
    func tablesStayInTheCalibrationArea(path: String) throws {
        let fw = try load(path)
        for t in try #require(fw.definition).tables {
            // The MAF table sits wherever the build put it (0x4581 in J5V13F02, 0xA7E0 in J5V26L52).
            if t.type != .u16split {
                #expect(t.address >= 0x5F00 && t.byteRange.upperBound <= 0xA000, "\(path): \(t.id)")
            }
            for axis in [t.xAxis, t.yAxis].compactMap({ $0 }) {
                #expect(fw.definition?.axes[axis] != nil, "\(path): \(t.id) → \(axis)")
            }
        }
    }

    /// Ignition maps hold plausible angles, mixture maps plausible AFR — in every build where
    /// they are named (by analogy with L19 or by the result's destination).
    @Test(arguments: images)
    func namedMapsHavePlausibleValues(path: String) throws {
        let fw = try load(path)
        for t in try #require(fw.definition).tables where t.rows == 16 {
            let values = fw.values(of: t)
            if t.group == "Зажигание" {
                #expect(values.allSatisfy { (-20...70).contains($0) }, "\(path): \(t.id) \(t.name)")
            }
            if t.unit == "AFR" {
                #expect(values.allSatisfy { (8...20).contains($0) }, "\(path): \(t.id) \(t.name)")
            }
        }
    }

    /// MAF characteristic, found by the ADC routine in every build: rising air flow, and in all
    /// serials but J5V05F16 the same curve (65.5 / 166.5 / 838 kg/h at codes 0 / 128 / 255).
    @Test(arguments: images)
    func mafTableInEveryBuild(path: String) throws {
        let fw = try load(path)
        let maf = try #require(fw.definition?.tables.first { $0.type == .u16split }, "\(path)")
        #expect(maf.name.contains("ДМРВ") && maf.cols == 256 && maf.unit == "кг/ч")
        let v = fw.values(of: maf)
        #expect(zip(v, v.dropFirst()).allSatisfy { $0 <= $1 }, "\(path)")
        if fw.softwareID != "J5V05F16" {
            #expect([v[0], v[128], v[255]] == [65.5, 166.5, 838], "\(path): \(v[0]) \(v[128]) \(v[255])")
        }
        let overlapping = fw.definition!.tables.filter {
            $0.id != maf.id && $0.byteRange.overlaps(maf.byteRange)
        }
        #expect(overlapping.isEmpty, "\(path): \(overlapping.map(\.id))")
    }

    /// Low byte at T + i, high byte at T + 100h + i.
    @Test func mafTableWritesBothPages() throws {
        var fw = try load("j5/j5v05l19/J5V05L19.BIN")
        let maf = try #require(fw.definition?.tables.first { $0.id == "t99B9" })
        #expect(maf.offsets(ofCell: 10) == [0x99C3, 0x9AC3])
        fw.setValue(300.1, of: maf, row: 0, col: 10)
        #expect(fw.data[0x99C3] == 0xB9 && fw.data[0x9AC3] == 0x0B) // 3001 = 0x0BB9
        #expect(fw.values(of: maf)[10] == 300.1)
    }

    /// Same ID, different code: J5V05J16 and its HIP9011 build each get their own layout.
    @Test func buildsSharingAnIDAreToldApart() throws {
        let stock = try #require(try load("j5/j5v05j16/J5v05j16.bin").definition)
        let hip = try #require(try load("j5/J5V05J16-9011-ok/J5V05J16-9011-ok.bin").definition)
        #expect(stock.softwareIDs == hip.softwareIDs)
        #expect(stock.check?.first?.address != hip.check?.first?.address)
        #expect(!stock.matches(try load("j5/J5V05J16-9011-ok/J5V05J16-9011-ok.bin").data))
    }

    /// The reference build keeps every hand-made description; CTP maps name the rest.
    @Test func referenceBuildKeepsItsNames() throws {
        let def = try #require(try load("j5/j5v05l19/J5V05L19.BIN").definition)
        func t(_ id: String) throws -> TableDefinition { try #require(def.tables.first { $0.id == id }, "\(id)") }
        #expect(try t("t6AC8").name == "УОЗ A (основной режим)")
        #expect(try t("t7F67").scale == 1.0 / 128) // traced in code; the CTP map says /256
        #expect(try t("t6104").cols == 51)
        #expect(def.tables.filter { $0.confidence != .auto }.count > 250)
    }

    /// Names, scales and shapes from the CTP maps of J5V05N35/J5V03K22 (same layout).
    @Test func ctpNamesCarryOver() throws {
        let def = try #require(try load("j5/j5v05l19/J5V05L19.BIN").definition)
        func t(_ id: String) throws -> TableDefinition { try #require(def.tables.first { $0.id == id }, "\(id)") }
        #expect(try t("t6056").name == "Число дополнительных искр")
        #expect(try t("t5F74").name == "Зона нечувствительности по дросселю") // replaced our guess
        let purge = try t("t76EF") // a scalar for the code scan, a 16×16 map in CTP
        #expect(purge.rows == 16 && purge.cols == 16 && purge.type == .s8)
        #expect(try t("t63D3").mask == 3)
        #expect(try t("f6051.0").name == "Датчик концентрации кислорода")
        // Not carried by address to builds with another layout: there names come only through
        // J5V07G26 by code context (see the next test).
        let i27 = try #require(try load("j5/j5v07i27/J5v07i27.bin").definition)
        #expect(!i27.tables.contains { $0.notes?.hasPrefix("По карте CTP") == true })
    }

    /// J5V07I27/J28 moved their calibrations: names come from J5V07G26 where the code around a
    /// table reference is the same and the data look alike.
    @Test(arguments: ["j5/j5v07i27/J5v07i27.bin", "j5/j5v07j28/J5v07j28.bin"])
    func namesByCodeContext(path: String) throws {
        let def = try #require(try load(path).definition)
        let carried = def.tables.filter { $0.notes?.hasPrefix("По совпадению кода с J5V07G26") == true }
        #expect(carried.count > 100, "\(carried.count)")
        #expect(carried.allSatisfy { $0.confidence == .likely })
        // The fan switch-on temperature moved from 60C8 (G26) to 607D.
        #expect(def.tables.first { $0.id == "t607D" }?.name == "Температура включения вентилятора")
    }

    /// Points settled by J5V05L19 code (docs/ctp-maps.md, «Сверка с кодом»).
    @Test func codeCheckedNotes() throws {
        let def = try #require(try load("j5/j5v05l19/J5V05L19.BIN").definition)
        func notes(_ id: String) -> String { def.tables.first { $0.id == id }?.notes ?? "" }
        #expect(notes("t6AC8").contains("не должны переходить через 0°"))
        #expect(notes("t76EF").contains("FD00"))
        #expect(notes("t6FE4").contains("37 точек"))
        #expect(def.tables.first { $0.id == "t7E07" }?.offset == 0.5)
    }
}
